import React from "react";
import './row.css';

interface RowProps {
    word: string;
}

const Row: React.FC<RowProps> = ({word}) => {
    return(
        <>
            <div className="rowcontainer">
                <div>{word[0]}</div>
                <div>{word[1]}</div>
                <div>{word[2]}</div>
                <div>{word[3]}</div>
                <div>{word[4]}</div>
            </div>
        </>
    );
}

export default Row;
